        static_assert(sizeof(E::Asset) == sizeof(AssetHandle));

        std::string to_std_string(rust::Str text) {
            return std::string{text.data(), text.size()};
        }

        UString to_ustring(rust::Str text) {
            const std::string_view view{text.data(), text.size()};
            if (auto converted = UString::try_from_utf8(view)) {
                return std::move(*converted);
            }
            return UString{};
        }

        rust::String to_rust_string(const UString &text) {
            const auto view = text.cpp_string_view();
            return rust::String::lossy(view.data(), view.size());
        }

        rust::String to_rust_string(const std::filesystem::path &path) {
            const auto text = path.string();
            return rust::String::lossy(text.data(), text.size());
        }

        // `E::Asset`'s private fields (owner_, id_, generation_, type_) and `AssetHandle`'s public
        // ones share layout by construction; this is the same bit-copy trick FFI/Gltf.cpp uses to
        // cross its ABI boundary.
        E::Asset to_engine_asset(const AssetHandle &handle) noexcept {
            E::Asset asset{};
            std::memcpy(&asset, &handle, sizeof(asset));
            return asset;
        }

        AssetHandle to_asset_handle(const E::Asset &asset) noexcept {
            AssetHandle handle{};
            std::memcpy(&handle, &asset, sizeof(handle));
            return handle;
        }

        AssetErrorCode map(E::AssetErrorCode code) noexcept {
            switch (code) {
            case E::AssetErrorCode::InvalidAsset: return AssetErrorCode::InvalidAsset;
            case E::AssetErrorCode::WrongType: return AssetErrorCode::WrongType;
            case E::AssetErrorCode::NotFound: return AssetErrorCode::NotFound;
            case E::AssetErrorCode::IoFailure: return AssetErrorCode::IoFailure;
            case E::AssetErrorCode::DecodeFailure: return AssetErrorCode::DecodeFailure;
            case E::AssetErrorCode::InvalidDescription: return AssetErrorCode::InvalidDescription;
            case E::AssetErrorCode::BackendFailure: return AssetErrorCode::BackendFailure;
            case E::AssetErrorCode::InUse: return AssetErrorCode::InUse;
            case E::AssetErrorCode::Unsupported: return AssetErrorCode::Unsupported;
            }
            return AssetErrorCode::BackendFailure;
        }

        E::TextureColorSpace map(TextureColorSpace v) noexcept {
            return v == TextureColorSpace::Linear ? E::TextureColorSpace::Linear : E::TextureColorSpace::Srgb;
        }

        TextureColorSpace map(E::TextureColorSpace v) noexcept {
            return v == E::TextureColorSpace::Linear ? TextureColorSpace::Linear : TextureColorSpace::Srgb;
        }

        E::TextureKind map(TextureKind v) noexcept {
            switch (v) {
            case TextureKind::ColorAlpha: return E::TextureKind::ColorAlpha;
            case TextureKind::ColorOpaque: return E::TextureKind::ColorOpaque;
            case TextureKind::Mask: return E::TextureKind::Mask;
            case TextureKind::NormalMap: return E::TextureKind::NormalMap;
            case TextureKind::MetallicRoughness: return E::TextureKind::MetallicRoughness;
            }
            return E::TextureKind::ColorAlpha;
        }

        E::TextureDynamicRange map(TextureDynamicRange v) noexcept {
            return v == TextureDynamicRange::Hdr ? E::TextureDynamicRange::Hdr : E::TextureDynamicRange::Sdr;
        }

        E::TexturePixelFormat map(TexturePixelFormat v) noexcept {
            return v == TexturePixelFormat::Rgba16Float ? E::TexturePixelFormat::Rgba16Float
                                                          : E::TexturePixelFormat::Rgba8;
        }

        std::vector<std::byte> to_byte_vector(rust::Slice<const std::uint8_t> bytes) {
            std::vector<std::byte> out(bytes.size());
            if (!bytes.empty()) {
                std::memcpy(out.data(), bytes.data(), bytes.size());
            }
            return out;
        }

        glm::vec3 to_vec3(const std::array<float, 3> &v) noexcept { return glm::vec3{v[0], v[1], v[2]}; }
        glm::vec2 to_vec2(const std::array<float, 2> &v) noexcept { return glm::vec2{v[0], v[1]}; }
        glm::vec4 to_vec4(const std::array<float, 4> &v) noexcept { return glm::vec4{v[0], v[1], v[2], v[3]}; }

        GltfLightKind map(E::GltfLightKind v) noexcept {
            switch (v) {
            case E::GltfLightKind::Directional: return GltfLightKind::Directional;
            case E::GltfLightKind::Point: return GltfLightKind::Point;
            case E::GltfLightKind::Spot: return GltfLightKind::Spot;
            }
            return GltfLightKind::Point;
        }

        void copy_transform(const glm::mat4 &m, std::array<float, 16> &out) noexcept {
            std::memcpy(out.data(), &m, sizeof(float) * 16);
        }

        template <typename Outcome>
        Outcome make_failure(Outcome outcome, AssetErrorCode error, rust::String message) {
            outcome.ok = false;
            outcome.error = error;
            outcome.message = std::move(message);
            return outcome;
        }

        template <typename Outcome>
        Outcome make_failure(AssetErrorCode error, rust::String message) {
            return make_failure(Outcome{}, error, std::move(message));
        }

        template <typename Outcome>
        Outcome make_exception_failure() {
            return make_failure<Outcome>(AssetErrorCode::BackendFailure,
                                         rust::String{"an unexpected C++ exception was caught at the FFI boundary"});
        }

        AssetOutcome asset_outcome(const E::AssetExpected<E::Asset> &result) {
            AssetOutcome outcome{};
            if (result) {
                outcome.ok = true;
                outcome.error = AssetErrorCode::None;
                outcome.asset = to_asset_handle(*result);
                return outcome;
            }
            outcome.ok = false;
            outcome.error = map(result.error().code);
            outcome.message = to_rust_string(result.error().message);
            return outcome;
        }

        StatusOutcome status_outcome(const E::AssetResult &result) {
            StatusOutcome outcome{};
            if (result) {
                outcome.ok = true;
                outcome.error = AssetErrorCode::None;
                return outcome;
            }
            outcome.ok = false;
            outcome.error = map(result.error().code);
            outcome.message = to_rust_string(result.error().message);
            return outcome;
        }

