    bool assets_generate_shape(ShapeKind shape, const ShapeParams &params, rust::Vec<ModelVertex> &out_vertices,
                               rust::Vec<std::uint32_t> &out_indices) {
        namespace R = SFT::Renderer;
        for (float value : {params.size, params.extents[0], params.extents[1], params.extents[2], params.radius,
                            params.height, params.width, params.depth, params.major_radius, params.minor_radius}) {
            if (!std::isfinite(value)) {
                return false;
            }
        }
        const R::Axis axis = params.axis == ShapeAxis::X ? R::Axis::X : params.axis == ShapeAxis::Z ? R::Axis::Z : R::Axis::Y;
        try {
            R::Mesh mesh;
            switch (shape) {
            case ShapeKind::Cube: mesh = R::Mesh::cube(R::CubeParams{.size = params.size}); break;
            case ShapeKind::Box:
                mesh = R::Mesh::rectangular_prism(R::RectangularPrismParams{.extents = to_vec3(params.extents)});
                break;
            case ShapeKind::UvSphere:
                mesh = R::Mesh::uv_sphere(R::UvSphereParams{.radius = params.radius, .rings = params.rings, .segments = params.segments});
                break;
            case ShapeKind::IcoSphere:
                mesh = R::Mesh::ico_sphere(R::IcoSphereParams{.radius = params.radius, .subdivisions = params.subdivisions});
                break;
            case ShapeKind::Plane:
                mesh = R::Mesh::plane(R::PlaneParams{.width = params.width,
                                                     .depth = params.depth,
                                                     .width_segments = params.width_segments,
                                                     .depth_segments = params.depth_segments,
                                                     .axis = axis});
                break;
            case ShapeKind::Cylinder:
                mesh = R::Mesh::cylinder(R::CylinderParams{.radius = params.radius,
                                                           .height = params.height,
                                                           .radial_segments = params.radial_segments,
                                                           .axis = axis,
                                                           .capped = params.capped});
                break;
            case ShapeKind::Cone:
                mesh = R::Mesh::cone(R::ConeParams{.radius = params.radius,
                                                   .height = params.height,
                                                   .radial_segments = params.radial_segments,
                                                   .axis = axis,
                                                   .capped = params.capped});
                break;
            case ShapeKind::Torus:
                mesh = R::Mesh::torus(R::TorusParams{.major_radius = params.major_radius,
                                                     .minor_radius = params.minor_radius,
                                                     .major_segments = params.major_segments,
                                                     .minor_segments = params.minor_segments});
                break;
            case ShapeKind::Tetrahedron: mesh = R::Mesh::tetrahedron(R::TetrahedronParams{.size = params.size}); break;
            default: return false;
            }
            if (mesh.vertices().empty() || mesh.indices().empty()) {
                return false;
            }
            out_vertices.reserve(mesh.vertices().size());
            for (const R::GeometryVertex &v : mesh.vertices()) {
                ModelVertex out{};
                out.position = {v.position.x, v.position.y, v.position.z};
                out.normal = {v.normal.x, v.normal.y, v.normal.z};
                out.uv = {v.uv.x, v.uv.y};
                out.color = {v.color.x, v.color.y, v.color.z, v.color.w};
                out.tangent = {v.tangent.x, v.tangent.y, v.tangent.z, v.tangent.w};
                out_vertices.push_back(out);
            }
            out_indices.reserve(mesh.indices().size());
            for (std::uint32_t index : mesh.indices()) {
                out_indices.push_back(index);
            }
            return true;
        } catch (const std::exception &) {
            return false;
        }
    }

    AssetOutcome assets_create_model(EngineView &engine, rust::Str label,
                                     rust::Slice<const ModelPrimitiveInput> primitives) {
        try {
            E::ModelAssetDesc desc{};
            desc.label = to_ustring(label);
            desc.primitives.reserve(primitives.size());
            for (const auto &primitive : primitives) {
                std::vector<SFT::Renderer::GeometryVertex> vertices;
                vertices.reserve(primitive.vertices.size());
                for (const auto &v : primitive.vertices) {
                    vertices.push_back(SFT::Renderer::GeometryVertex{
                        .position = to_vec3(v.position),
                        .normal = to_vec3(v.normal),
                        .uv = to_vec2(v.uv),
                        .color = to_vec4(v.color),
                        .tangent = to_vec4(v.tangent),
                    });
                }
                std::vector<std::uint32_t> indices(primitive.indices.begin(), primitive.indices.end());

                E::ModelPrimitiveDesc primitive_desc{};
                primitive_desc.mesh = SFT::Renderer::Mesh::from_vertices(vertices, indices);
                primitive_desc.shader = to_engine_asset(primitive.shader);
                if (primitive.has_vertex_color) {
                    primitive_desc.vertex_color = to_vec4(primitive.vertex_color);
                }
                primitive_desc.textures.reserve(primitive.textures.size());
                for (const auto &binding : primitive.textures) {
                    primitive_desc.textures.push_back(E::ModelTextureBinding{
                        .slot = to_ustring(binding.slot),
                        .texture = to_engine_asset(binding.texture),
                    });
                }
                primitive_desc.double_sided = primitive.double_sided;
                desc.primitives.push_back(std::move(primitive_desc));
            }
            return asset_outcome(engine.assets().create_model(std::move(desc)));
        } catch (const std::exception &) {
            return make_exception_failure<AssetOutcome>();
        }
    }

