    AssetInfoOutcome assets_info(const EngineView &engine, AssetHandle asset) {
        try {
            const auto result = engine.assets().info(to_engine_asset(asset));
            AssetInfoOutcome outcome{};
            if (!result) {
                outcome.ok = false;
                outcome.error = map(result.error().code);
                outcome.message = to_rust_string(result.error().message);
                return outcome;
            }
            outcome.ok = true;
            outcome.error = AssetErrorCode::None;
            outcome.asset = to_asset_handle(result->asset);
            outcome.label = to_rust_string(result->label);
            outcome.source = to_rust_string(result->source);
            outcome.memory_bytes = static_cast<std::uint64_t>(result->memory_bytes);
            outcome.loaded = result->loaded;
            return outcome;
        } catch (const std::exception &) {
            return make_exception_failure<AssetInfoOutcome>();
        }
    }

