    BytesOutcome assets_file_bytes(const EngineView &engine, AssetHandle asset) {
        try {
            const auto result = engine.assets().file_bytes(to_engine_asset(asset));
            BytesOutcome outcome{};
            if (!result) {
                outcome.ok = false;
                outcome.error = map(result.error().code);
                outcome.message = to_rust_string(result.error().message);
                return outcome;
            }
            outcome.ok = true;
            outcome.error = AssetErrorCode::None;
            const auto &bytes = **result;
            outcome.data.reserve(bytes.size());
            for (const auto b : bytes) {
                outcome.data.push_back(static_cast<std::uint8_t>(b));
            }
            return outcome;
        } catch (const std::exception &) {
            return make_exception_failure<BytesOutcome>();
        }
    }

